import json,re,hashlib
from pathlib import Path
P=Path('private/09_human_rating_collection/preparation_11-09-2026/native_harness_packet_11-11-2026')
E=Path('experiments/09_prepare_packets_and_collect_human_ratings')
# 1 ledger arithmetic
for led in sorted(P.glob('runs/*/*/gateway_ledger.json')):
    L=json.load(open(led)); obs=0; unsettled=0; n=0
    for r in L['requests']:
        u=r.get('usage_metadata') or r.get('usage') or {}
        if 'promptTokenCount' in u:
            obs+=u['promptTokenCount']*0.75e-6+(u.get('candidatesTokenCount',0)+u.get('thoughtsTokenCount',0))*3.75e-6; n+=1
            assert u.get('totalTokenCount',0)==u['promptTokenCount']+u.get('candidatesTokenCount',0)+u.get('thoughtsTokenCount',0), ('other billed category?',r.get('call'))
        else: unsettled+=r.get('reserved_usd',0)
    print('ledger',led.parts[-3]+'/'+led.parts[-2][:34],'requests',len(L['requests']),'with usage',n,'recomputed observed $%.7f + retained reservations $%.6f = $%.7f | ledger accounted $%.7f | cap %s'%(obs,unsettled,obs+unsettled,L['accounted_usd'],L.get('cap_usd')))
# 2 credential patterns
pat=re.compile(rb'sk-ant-oat\d{2}-[A-Za-z0-9_-]{20,}|AIza[0-9A-Za-z_-]{30,}|sk-ant-api\d{2}-[A-Za-z0-9_-]{20,}')
hits=[];nf=0
for f in list(P.rglob('*'))+list((E/'support/scripts/native_packet_generation').glob('*.py')):
    if f.is_file() and not f.is_symlink() and f.name!='review_stream.jsonl':
        nf+=1
        if pat.search(f.read_bytes()): hits.append(str(f)[-80:])
print('credential-pattern scan: files',nf,'files with hits',len(hits),hits[:5])
# 3 network-ish tool commands in trajectories
net=re.compile(r'curl|wget|https?://|urllib|requests\.|socket|\bnc\b|provider-gateway|ttj-native-egress|printenv|environ|_PROXY|OAUTH|API_KEY|\bgit (clone|fetch|pull)|pip install|npm i',re.I)
tot=0;flag=[]
for tr in sorted(P.glob('runs/*/*/trajectory.jsonl')):
    for line in open(tr,errors='replace'):
        try:e=json.loads(line)
        except Exception: continue
        if e.get('type')=='message_end' and e.get('message',{}).get('role')=='assistant':
            for c in e['message'].get('content',[]) or []:
                if c.get('type')=='toolCall':
                    tot+=1; s=json.dumps(c.get('arguments'))
                    if net.search(s): flag.append((tr.parts[-3]+'/'+tr.parts[-2][:24],s[:110]))
for st in sorted(P.glob('claude_code_*/*/stream.jsonl')):
    for line in open(st,errors='replace'):
        try:e=json.loads(line)
        except Exception: continue
        if e.get('type')=='assistant':
            for c in e.get('message',{}).get('content',[]) or []:
                if c.get('type')=='tool_use':
                    tot+=1; s=json.dumps(c.get('input'))
                    if net.search(s): flag.append((st.parts[-3][:18]+'/'+st.parts[-2][:24],s[:110]))
print('tool calls scanned',tot,'network/credential-like matches',len(flag));
for x in flag[:6]: print('   ',x)
# 4 guide columns
g=(E/'rating_task_packet/RATING_FORM_GUIDE.md').read_text()
cols=['rater_name','rater_id','item_id','task_folder','candidate_file','final_score_0_5','ai_assisted_rating_attestation','minutes_spent','confidence','rationale','problem_note']
print('guide lacks column names:',[c for c in cols if c not in g],'| guide bytes',len(g))
sha=lambda p: hashlib.sha256(Path(p).read_bytes()).hexdigest()[:16]
print({p.name:sha(p) for p in sorted((E/'support/scripts/native_packet_generation').glob('*.py'))})
s=json.load(open(P/'runs/pi_valid_v3/BATCH_STATUS.json')); print('PI now',s['status'],len(s['cells']),'terminal;',[(c['task_id'][-22:],c['status'],c['artifact_status'],c['provider_requests']) for c in s['cells'][2:]])
EOF
date

